fun largestNum(num: Int): Int {
    var digits = num.toString().toCharArray()
    for (i in digits.indices.reversed()) {
        for (j in i - 1 downTo 0) {
            if (digits[i] % 2 == digits[j] % 2) {
                val temp = digits[i]
                digits[i] = digits[j]
                digits[j] = temp
