func maxDistToClosest(_ seats: [Int]) -> Int {
    var maxDist = 0
    var lastPerson = -1

    for i in 0..<seats.count {
        if seats[i] == 1 {
            if lastPerson == -1 {
                maxDist = i
            } else {
                maxDist = max(maxDist, (i - lastPerson) / 2)
